\label{lem:cont}
The functions $\mathcal M(t):=\max_{p\in B_t}p\cdot\hat{y}$ and
$m(t):=\min_{p\in B_t}p\cdot\hat{y}$ are continuous on $[0,1]$.

\label{lem:calc}
For $u>\sqrt2$, with $\mu_*(u)=\frac{u^2-2}{u^2+2}$ and
$\mu_{\mathrm{cap}}(u):=\frac{\sqrt{u^2-2}}{u}$:
\begin{enumerate}
\item[(a)] $0<\mu_*(u)\le\mu_{\mathrm{cap}}(u)<1$, and
$g(\mu_*(u))=B_1(u)$, $g(\mu_{\mathrm{cap}}(u))=B_2(u)$;
\item[(b)] $g$ is strictly decreasing on $(0,1/\sqrt2\,]$ and strictly
increasing on $[\,1/\sqrt2,1)$, with $g(1/\sqrt2)=4$;
\item[(c)] $B_1$ is strictly decreasing on $(\sqrt2,\,2+\sqrt2)$ and
$B_1(2+\sqrt2)=4$; $B_2$ is strictly decreasing on $(\sqrt2,2)$ and strictly
increasing on $(2,\infty)$;
\item[(d)] $B_1=B_2$ has a unique solution $u_B$ in $(2,\,2+\sqrt2)$, and
$u_B\in(2.60114,\,2.60115)$; moreover
$\Psi(u)\ge\Psi(u_B)=B_1(u_B)$ for all $u>\sqrt2$, and
$\Psi(u_B)\le B_1(2.60114)=4.2861666\ldots<4.2862$.
\end{enumerate}

\label{lem:seg}
Let $M>1$ and let $(B,g)$ traverse $K_M$ weakly.  Then every straight
segment contained in $B$ has length at most $3$.

\label{cor:convex}
For $M>1$, every \emph{convex} body that weakly traverses $K_M$ has
diameter at most $3$ and volume at most $3$.

\label{lem:axisconv}
The intersection of $K_M$ with every line parallel to a coordinate axis is
a (possibly empty or unbounded) interval.
